import type { Context } from '../../context';
import type { Message } from '../../network/api';
import type { MaybeArray } from '../../types';
/** Функция-триггер получает Context, а найденное совпадение попадает в `ctx.match`. */
export type TriggerFn<Ctx extends Context> = (value: string, ctx: Ctx) => RegExpExecArray | null;
export type Triggers<Ctx extends Context = Context> = MaybeArray<string | RegExp | TriggerFn<Ctx>>;
export declare const normalizeTriggers: <Ctx extends Context>(triggers: Triggers<Ctx>) => TriggerFn<Ctx>[];
export declare const extractTextFromMessage: (message: Message, myId?: number) => string | null | undefined;
